-- ===== Procurement =====
CREATE TABLE purchase_orders (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    po_no       TEXT NOT NULL UNIQUE,
    supplier_id UUID NOT NULL REFERENCES suppliers(id),
    status      TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','PARTIAL','RECEIVED','CANCELLED')),
    ordered_on  DATE NOT NULL DEFAULT CURRENT_DATE,
    expected_on DATE,
    notes       TEXT NOT NULL DEFAULT '',
    created_by  UUID REFERENCES users(id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE po_lines (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    po_id           UUID NOT NULL REFERENCES purchase_orders(id) ON DELETE CASCADE,
    raw_material_id UUID NOT NULL REFERENCES raw_materials(id),
    qty_ordered     NUMERIC(18,4) NOT NULL CHECK (qty_ordered > 0),   -- purchase units
    qty_received    NUMERIC(18,4) NOT NULL DEFAULT 0                  -- purchase units
);
CREATE TABLE grns (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    grn_no      TEXT NOT NULL UNIQUE,
    po_id       UUID REFERENCES purchase_orders(id),
    supplier_id UUID NOT NULL REFERENCES suppliers(id),
    received_on DATE NOT NULL DEFAULT CURRENT_DATE,
    challan_no  TEXT NOT NULL DEFAULT '',
    vehicle_no  TEXT NOT NULL DEFAULT '',
    notes       TEXT NOT NULL DEFAULT '',
    received_by UUID REFERENCES users(id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE grn_lines (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),   -- also the stock lot_id
    grn_id          UUID NOT NULL REFERENCES grns(id) ON DELETE CASCADE,
    raw_material_id UUID NOT NULL REFERENCES raw_materials(id),
    po_line_id      UUID REFERENCES po_lines(id),
    qty_purchase    NUMERIC(18,4) NOT NULL CHECK (qty_purchase > 0),  -- purchase units
    qty_stock       NUMERIC(18,4) NOT NULL CHECK (qty_stock > 0),     -- converted to stock units
    lot_no          TEXT NOT NULL DEFAULT '',
    expiry_date     DATE
);
CREATE TABLE reorder_recommendations (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    raw_material_id  UUID NOT NULL REFERENCES raw_materials(id) ON DELETE CASCADE,
    status           TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','ORDERED','DISMISSED','RESOLVED')),
    reason           TEXT NOT NULL CHECK (reason IN ('BELOW_MIN','BURN_RATE','BOTH')),
    current_stock    NUMERIC(18,4) NOT NULL,           -- stock units
    min_stock        NUMERIC(18,4) NOT NULL,
    avg_daily_burn   NUMERIC(18,4) NOT NULL,
    days_cover       NUMERIC(18,2),                    -- null when burn = 0
    lead_time_days   INT NOT NULL,
    safety_days      INT NOT NULL,
    reorder_point    NUMERIC(18,4) NOT NULL,
    suggested_qty_purchase NUMERIC(18,4) NOT NULL,     -- purchase units (rounded up)
    suggested_supplier_id UUID REFERENCES suppliers(id),
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX reorder_open_uq ON reorder_recommendations (raw_material_id) WHERE status = 'OPEN';

-- ===== Ledger-based zone warehouse =====
CREATE TABLE stock_balances (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    item_type   TEXT NOT NULL CHECK (item_type IN ('RAW','PRODUCT')),
    item_id     UUID NOT NULL,
    zone        TEXT NOT NULL CHECK (zone IN ('RM_STORE','BLOW_FLOOR','QC_QUARANTINE','FG_READY','SCRAP_YARD','JAR_EMPTY','JAR_CLEAN')),
    lot_id      UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000', -- grn_lines.id (RAW) / production_batches.id (PRODUCT) / nil
    qty         NUMERIC(18,4) NOT NULL DEFAULT 0 CHECK (qty >= 0),
    expiry_date DATE,                       -- FEFO key
    received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (item_type, item_id, zone, lot_id)
);
CREATE INDEX stock_balances_item_idx ON stock_balances (item_type, item_id, zone);

CREATE TABLE stock_ledger (
    id            BIGSERIAL PRIMARY KEY,
    at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    txn_group     UUID NOT NULL,
    item_type     TEXT NOT NULL,
    item_id       UUID NOT NULL,
    zone          TEXT NOT NULL,
    lot_id        UUID NOT NULL,
    qty_delta     NUMERIC(18,4) NOT NULL CHECK (qty_delta <> 0),
    balance_after NUMERIC(18,4) NOT NULL CHECK (balance_after >= 0),
    txn_type      TEXT NOT NULL,   -- GRN, BLOW_ISSUE, BLOW_OUTPUT, BLOW_SCRAP, BATCH_CONSUME, BATCH_OUTPUT, QC_RELEASE, QC_REJECT, GATE_PASS, TRIP_RETURN, TRIP_DAMAGED, JAR_WASH, JAR_RECEIVE, JAR_WRITE_OFF, ADJUST, TRANSFER
    ref_type      TEXT,
    ref_id        UUID,
    note          TEXT NOT NULL DEFAULT '',
    user_id       UUID
);
CREATE INDEX stock_ledger_item_idx ON stock_ledger (item_type, item_id, at DESC);
CREATE INDEX stock_ledger_ref_idx ON stock_ledger (ref_type, ref_id);
CREATE INDEX stock_ledger_type_at_idx ON stock_ledger (txn_type, at DESC);
CREATE TRIGGER stock_ledger_immutable BEFORE UPDATE OR DELETE ON stock_ledger
    FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- ===== Production =====
CREATE TABLE blow_molding_runs (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    run_no              TEXT NOT NULL UNIQUE,
    run_date            DATE NOT NULL DEFAULT CURRENT_DATE,
    shift               TEXT NOT NULL DEFAULT 'DAY' CHECK (shift IN ('DAY','NIGHT','GENERAL')),
    equipment_id        UUID REFERENCES equipment(id),
    preform_material_id UUID NOT NULL REFERENCES raw_materials(id),
    bottle_material_id  UUID NOT NULL REFERENCES raw_materials(id),
    preforms_issued     NUMERIC(18,4) NOT NULL CHECK (preforms_issued > 0),
    good_bottles        NUMERIC(18,4) NOT NULL CHECK (good_bottles >= 0),
    scrap_pcs           NUMERIC(18,4) NOT NULL CHECK (scrap_pcs >= 0),
    scrap_pct           NUMERIC(8,3) NOT NULL,
    scrap_weight_kg     NUMERIC(14,4),
    notes               TEXT NOT NULL DEFAULT '',
    created_by          UUID REFERENCES users(id),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (good_bottles + scrap_pcs = preforms_issued)
);

CREATE TABLE water_treatment_logs (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    logged_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    tds_ppm      NUMERIC(10,2) NOT NULL,
    ph           NUMERIC(5,2)  NOT NULL,
    ozone_ppm    NUMERIC(8,3),
    uv_ok        BOOLEAN NOT NULL DEFAULT true,
    minerals     JSONB NOT NULL DEFAULT '{}'::jsonb,   -- { "Calcium chloride": 1.2, ... }  (ppm or grams dosed)
    out_of_range BOOLEAN NOT NULL DEFAULT false,
    notes        TEXT NOT NULL DEFAULT '',
    logged_by    UUID REFERENCES users(id)
);
CREATE INDEX water_logs_at_idx ON water_treatment_logs (logged_at DESC);

CREATE TABLE production_batches (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    batch_no       TEXT NOT NULL UNIQUE,
    product_id     UUID NOT NULL REFERENCES products(id),
    produced_on    DATE NOT NULL DEFAULT CURRENT_DATE,
    shift          TEXT NOT NULL DEFAULT 'DAY' CHECK (shift IN ('DAY','NIGHT','GENERAL')),
    crates         INT NOT NULL CHECK (crates > 0),     -- crates (or jars for JAR20L) produced
    qc_status      TEXT NOT NULL DEFAULT 'QUARANTINE' CHECK (qc_status IN ('QUARANTINE','APPROVED','REJECTED')),
    mfg_date       DATE NOT NULL DEFAULT CURRENT_DATE,
    expiry_date    DATE NOT NULL,
    water_log_id   UUID REFERENCES water_treatment_logs(id),
    notes          TEXT NOT NULL DEFAULT '',
    qc_decided_by  UUID REFERENCES users(id),
    qc_decided_at  TIMESTAMPTZ,
    qc_notes       TEXT NOT NULL DEFAULT '',
    created_by     UUID REFERENCES users(id),
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX production_batches_status_idx ON production_batches (qc_status, created_at DESC);

CREATE TABLE batch_material_usage (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    batch_id        UUID NOT NULL REFERENCES production_batches(id) ON DELETE CASCADE,
    raw_material_id UUID NOT NULL REFERENCES raw_materials(id),
    qty             NUMERIC(18,4) NOT NULL,       -- stock units
    zone            TEXT NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX batch_usage_material_idx ON batch_material_usage (raw_material_id, created_at);

CREATE TABLE qc_tests (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    batch_id        UUID NOT NULL REFERENCES production_batches(id) ON DELETE CASCADE,
    tested_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    tested_by       UUID REFERENCES users(id),
    tds_ppm         NUMERIC(10,2),
    ph              NUMERIC(5,2),
    ozone_ppm       NUMERIC(8,3),
    turbidity_ntu   NUMERIC(8,3),
    microbial_ok    BOOLEAN,
    seal_ok         BOOLEAN,
    label_ok        BOOLEAN,
    result          TEXT NOT NULL CHECK (result IN ('PASS','FAIL')),
    remarks         TEXT NOT NULL DEFAULT ''
);

-- ===== QR crate sets, loading trips =====
CREATE TABLE loading_trips (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    trip_no            TEXT NOT NULL UNIQUE,
    vehicle_id         UUID NOT NULL REFERENCES vehicles(id),
    route_id           UUID REFERENCES routes(id),
    driver_name        TEXT NOT NULL DEFAULT '',
    capacity_crates    INT NOT NULL,                  -- snapshot of vehicle capacity
    status             TEXT NOT NULL DEFAULT 'LOADING' CHECK (status IN ('LOADING','DISPATCHED','SETTLED','CANCELLED')),
    gate_pass_no       TEXT UNIQUE,
    gate_pass_issued_at TIMESTAMPTZ,
    issued_by          UUID REFERENCES users(id),
    returned_at        TIMESTAMPTZ,
    settled_at         TIMESTAMPTZ,
    settled_by         UUID REFERENCES users(id),
    notes              TEXT NOT NULL DEFAULT '',
    created_by         UUID REFERENCES users(id),
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX loading_trips_status_idx ON loading_trips (status, created_at DESC);

CREATE TABLE qr_crate_sets (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code            TEXT NOT NULL UNIQUE,            -- value placed in the QR URL (?qr=CODE)
    batch_id        UUID NOT NULL REFERENCES production_batches(id),
    product_id      UUID NOT NULL REFERENCES products(id),
    set_label       TEXT NOT NULL,                   -- 'X','Y','Z',... or 'X-R1' for residual children
    seq             INT NOT NULL,
    parent_set_id   UUID REFERENCES qr_crate_sets(id),
    original_crates INT NOT NULL CHECK (original_crates > 0),
    crates          INT NOT NULL CHECK (crates >= 0),   -- current crates this label represents
    status          TEXT NOT NULL DEFAULT 'QUARANTINE' CHECK (status IN
                    ('QUARANTINE','AVAILABLE','RESERVED','LOADED','DELIVERED','REJECTED')),
    trip_id         UUID REFERENCES loading_trips(id),
    loaded_at       TIMESTAMPTZ,
    created_by      UUID REFERENCES users(id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX qr_sets_batch_idx ON qr_crate_sets (batch_id, seq);
CREATE INDEX qr_sets_status_idx ON qr_crate_sets (status);
CREATE INDEX qr_sets_trip_idx ON qr_crate_sets (trip_id);

CREATE TABLE trip_items (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    trip_id          UUID NOT NULL REFERENCES loading_trips(id) ON DELETE CASCADE,
    qr_set_id        UUID NOT NULL REFERENCES qr_crate_sets(id),
    batch_id         UUID NOT NULL REFERENCES production_batches(id),
    product_id       UUID NOT NULL REFERENCES products(id),
    crates           INT NOT NULL CHECK (crates > 0),
    crates_delivered INT,
    crates_returned  INT,    -- unsold, restocked
    crates_damaged   INT,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (trip_id, qr_set_id)
);

-- ===== 20L returnable jars (customer side). Plant-side jars live in stock_balances JAR_EMPTY / JAR_CLEAN =====
CREATE TABLE jar_ledger (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    customer_id UUID NOT NULL REFERENCES customers(id),
    product_id  UUID NOT NULL REFERENCES products(id),
    txn_type    TEXT NOT NULL CHECK (txn_type IN ('OPENING','ISSUE_FILLED','RETURN_EMPTY','DAMAGED','LOST','WRITE_OFF')),
    delta       INT NOT NULL CHECK (delta <> 0),   -- change in jars HELD BY CUSTOMER (+ issue/opening, - return/damaged/lost/write-off)
    txn_date    DATE NOT NULL DEFAULT CURRENT_DATE,
    trip_id     UUID REFERENCES loading_trips(id),
    note        TEXT NOT NULL DEFAULT '',
    created_by  UUID REFERENCES users(id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX jar_ledger_customer_idx ON jar_ledger (customer_id, product_id, txn_date);

-- ===== migrations/0007_events.sql =====
-- Realtime change notifications. Statement-level triggers publish a *topic name only* (never row data) on channel
-- `erp_events`; NOTIFY is delivered on COMMIT so rolled-back work never produces an event. src/events.rs listens,
-- debounces and fans out to browsers over SSE (/api/events), filtered per user by allowed_pages.
CREATE FUNCTION erp_notify() RETURNS trigger AS $$
BEGIN PERFORM pg_notify('erp_events', TG_ARGV[0]); RETURN NULL; END; $$ LANGUAGE plpgsql;

DO $$
DECLARE r RECORD;
BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('stock_balances','stock'),
    ('raw_materials','materials'), ('purchase_orders','materials'), ('po_lines','materials'), ('grns','materials'),
    ('grn_lines','materials'), ('reorder_recommendations','materials'),
    ('blow_molding_runs','production'), ('water_treatment_logs','production'), ('production_batches','production'),
    ('qc_tests','qc'),
    ('qr_crate_sets','qr'),
    ('loading_trips','trips'), ('trip_items','trips'),
    ('jar_ledger','jars'),
    ('maintenance_schedules','maintenance'), ('maintenance_logs','maintenance'), ('equipment','maintenance'), ('vehicles','maintenance'),
    ('alerts','alerts'), ('alert_reads','alerts'),
    ('suppliers','master'), ('products','master'), ('bom_items','master'), ('customers','master'), ('routes','master'),
    ('users','users'), ('system_settings','settings'), ('audit_logs','admin'), ('push_subscriptions','admin')
  ) AS t(tbl, topic) LOOP
    EXECUTE format('CREATE TRIGGER %I AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH STATEMENT EXECUTE FUNCTION erp_notify(%L)',
                   'evt_' || r.tbl, r.tbl, r.topic);
  END LOOP;
END $$;
-- a QC decision updates production_batches => also tell qc/qr listeners
CREATE TRIGGER evt_batches_qc AFTER UPDATE OF qc_status ON production_batches FOR EACH STATEMENT EXECUTE FUNCTION erp_notify('qc');

-- ===== migrations/0008_bulk_loading_idempotency.sql =====
-- Loading by gross stock (product/batch crates) is the default; QR crate-set labels are an OPTIONAL feature.
ALTER TABLE trip_items ALTER COLUMN qr_set_id DROP NOT NULL;
ALTER TABLE trip_items DROP CONSTRAINT trip_items_trip_id_qr_set_id_key;
CREATE UNIQUE INDEX trip_items_set_uq   ON trip_items (trip_id, qr_set_id) WHERE qr_set_id IS NOT NULL;
CREATE UNIQUE INDEX trip_items_batch_uq ON trip_items (trip_id, batch_id)  WHERE qr_set_id IS NULL;
CREATE INDEX trip_items_batch_idx ON trip_items (batch_id);

INSERT INTO system_settings (key, value, description) VALUES
 ('features.qr_labels',       'false', 'Enable optional QR crate-set labels (stickers). Off = load by product/batch crate counts only'),
 ('plant.utc_offset_minutes', '330',   'Plant local time offset from UTC in minutes (330 = IST). Used for "today" and document numbers');

-- Idempotency for retried POST/PUT/DELETE on weak plant Wi-Fi (Idempotency-Key header)
CREATE TABLE idempotency_keys (
    user_id    UUID NOT NULL,
    key        TEXT NOT NULL,
    method     TEXT NOT NULL,
    path       TEXT NOT NULL,
    fingerprint TEXT NOT NULL,   -- sha256(method|path|query|body): same key + different request => IDEMPOTENCY_CONFLICT
    status     INT,
    body       BYTEA,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, key)
);
CREATE INDEX idempotency_created_idx ON idempotency_keys (created_at);

-- ===== migrations/0009_documents_corrections.sql =====
-- Additional stock documents + correction (void/reverse) support. Principle: documents are never deleted and the ledger is
-- never edited; mistakes are corrected with VOID / reversing ledger rows linked to the original document + a reason.
CREATE SEQUENCE dn_seq; CREATE SEQUENCE wo_seq; CREATE SEQUENCE cnt_seq; CREATE SEQUENCE rtv_seq;

-- GRN void (wrong qty / duplicate entry)
ALTER TABLE grns ADD COLUMN status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','VOID'));
ALTER TABLE grns ADD COLUMN void_reason TEXT, ADD COLUMN voided_by UUID REFERENCES users(id), ADD COLUMN voided_at TIMESTAMPTZ;
-- a (supplier, challan) pair can only be entered once while ACTIVE => catches double entry
CREATE UNIQUE INDEX grns_challan_uq ON grns (supplier_id, lower(challan_no)) WHERE challan_no <> '' AND status = 'ACTIVE';

-- Gate-pass void (loaded the wrong goods / vehicle never left)
ALTER TABLE loading_trips ADD COLUMN void_reason TEXT, ADD COLUMN voided_by UUID REFERENCES users(id), ADD COLUMN voided_at TIMESTAMPTZ;

-- Direct dispatch / walk-in sale of finished goods (quantities only – no prices, taxes or payments)
CREATE TABLE dispatch_notes (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    dn_no         TEXT NOT NULL UNIQUE,
    customer_id   UUID REFERENCES customers(id),
    party_name    TEXT NOT NULL DEFAULT '',      -- walk-in name when no customer record
    vehicle_no    TEXT NOT NULL DEFAULT '',
    status        TEXT NOT NULL DEFAULT 'ISSUED' CHECK (status IN ('ISSUED','VOID')),
    note          TEXT NOT NULL DEFAULT '',
    void_reason   TEXT, voided_by UUID REFERENCES users(id), voided_at TIMESTAMPTZ,
    created_by    UUID REFERENCES users(id),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (customer_id IS NOT NULL OR party_name <> '')
);
CREATE TABLE dispatch_lines (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    dn_id       UUID NOT NULL REFERENCES dispatch_notes(id) ON DELETE CASCADE,
    product_id  UUID NOT NULL REFERENCES products(id),
    batch_id    UUID NOT NULL REFERENCES production_batches(id),
    crates      INT NOT NULL CHECK (crates > 0)
);
CREATE INDEX dispatch_lines_batch_idx ON dispatch_lines (batch_id);

-- Destroyed / written-off stock with a mandatory reason code
CREATE TABLE stock_write_offs (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    wo_no       TEXT NOT NULL UNIQUE,
    item_type   TEXT NOT NULL CHECK (item_type IN ('RAW','PRODUCT')),
    item_id     UUID NOT NULL,
    zone        TEXT NOT NULL,
    lot_id      UUID NOT NULL,
    qty         NUMERIC(18,4) NOT NULL CHECK (qty > 0),
    reason_code TEXT NOT NULL CHECK (reason_code IN ('BREAKAGE','EXPIRED','CONTAMINATED','SPILLAGE','QC_REJECT','THEFT_LOSS','TRANSIT_DAMAGE','OTHER')),
    note        TEXT NOT NULL,
    disposed    BOOLEAN NOT NULL DEFAULT false,   -- true = physically removed from SCRAP_YARD (DISPOSE ledger row)
    created_by  UUID REFERENCES users(id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Supplier returns (receipt rejected / defective goods sent back)
CREATE TABLE supplier_returns (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    rtv_no      TEXT NOT NULL UNIQUE,
    supplier_id UUID NOT NULL REFERENCES suppliers(id),
    grn_id      UUID REFERENCES grns(id),
    note        TEXT NOT NULL DEFAULT '',
    created_by  UUID REFERENCES users(id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE supplier_return_lines (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    return_id       UUID NOT NULL REFERENCES supplier_returns(id) ON DELETE CASCADE,
    raw_material_id UUID NOT NULL REFERENCES raw_materials(id),
    lot_id          UUID NOT NULL,
    qty_stock       NUMERIC(18,4) NOT NULL CHECK (qty_stock > 0),
    reason          TEXT NOT NULL DEFAULT ''
);

-- Physical stock count (cycle count): snapshot expected -> enter counted -> review variance -> post adjustments
CREATE TABLE stock_counts (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    cnt_no      TEXT NOT NULL UNIQUE,
    zone        TEXT NOT NULL,
    status      TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','POSTED','CANCELLED')),
    note        TEXT NOT NULL DEFAULT '',
    created_by  UUID REFERENCES users(id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    posted_by   UUID REFERENCES users(id),
    posted_at   TIMESTAMPTZ
);
CREATE TABLE stock_count_lines (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    count_id     UUID NOT NULL REFERENCES stock_counts(id) ON DELETE CASCADE,
    item_type    TEXT NOT NULL,
    item_id      UUID NOT NULL,
    lot_id       UUID NOT NULL,
    expected_qty NUMERIC(18,4) NOT NULL,
    counted_qty  NUMERIC(18,4) CHECK (counted_qty IS NULL OR counted_qty >= 0),
    note         TEXT NOT NULL DEFAULT '',
    UNIQUE (count_id, item_type, item_id, lot_id)
);

INSERT INTO system_settings (key, value, description) VALUES
 ('entry.large_adjust_pct',      '20', 'Adjustments/write-offs larger than this % of the balance need explicit confirm'),
 ('production.scrap_warn_pct',   '5',  'Blow-molding scrap % above which a note is required and a warning is shown'),
 ('loading.void_window_hours',   '12', 'Hours after issue during which a gate pass / dispatch note may be voided (Admin: unlimited)'),
 ('settle.damage_warn_pct',      '10', 'Trip settlement with damaged crates above this % of loaded needs confirm');

-- realtime topics for the new tables
DO $$ DECLARE r RECORD; BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('dispatch_notes','trips'), ('dispatch_lines','trips'), ('stock_write_offs','stock'), ('stock_counts','stock'),
    ('stock_count_lines','stock'), ('supplier_returns','materials'), ('supplier_return_lines','materials')
  ) AS t(tbl, topic) LOOP
    EXECUTE format('CREATE TRIGGER %I AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH STATEMENT EXECUTE FUNCTION erp_notify(%L)', 'evt_'||r.tbl, r.tbl, r.topic);
  END LOOP; END $$;

-- ===== migrations/0010_plant_specific.sql =====
-- Plant-specific product model.
--  * BOTTLED   = single-use PET SKU: bottle blown from a PREFORM (consumes preforms + caps + labels ...).
--  * RETURNABLE = reusable container (20 L jar etc.): NEVER consumes preforms/bottles; it is washed and refilled, tracked as a fleet.
ALTER TABLE products DROP CONSTRAINT products_kind_check;
UPDATE products SET kind = 'RETURNABLE' WHERE kind = 'JAR20L';
ALTER TABLE products ADD CONSTRAINT products_kind_check CHECK (kind IN ('BOTTLED','RETURNABLE'));

ALTER TABLE products
  ADD COLUMN crates_per_pallet   INT CHECK (crates_per_pallet IS NULL OR crates_per_pallet > 0),   -- standard pallet configuration
  ADD COLUMN preform_material_id UUID REFERENCES raw_materials(id),   -- which preform is blown for this SKU (BOTTLED only)
  ADD COLUMN bottle_material_id  UUID REFERENCES raw_materials(id),   -- the EMPTY_BOTTLE material that blowing produces for this SKU
  ADD COLUMN max_cycles          INT CHECK (max_cycles IS NULL OR max_cycles > 0);   -- retire a returnable after N fills (fleet estimate)
ALTER TABLE products ADD CONSTRAINT products_returnable_no_preform
  CHECK (kind = 'BOTTLED' OR (preform_material_id IS NULL AND bottle_material_id IS NULL));

-- Mineral / chemical dosing: PER_1000L means qty is stock-units per 1000 litres of water in the batch
-- (litres = crates x units_per_crate x size_ml / 1000), so one recipe scales across SKU sizes.
ALTER TABLE bom_items ADD COLUMN basis TEXT NOT NULL DEFAULT 'PER_CRATE' CHECK (basis IN ('PER_CRATE','PER_1000L'));

-- Returnable-container fleet lifecycle (aggregate counts; containers are not individually tagged)
CREATE TABLE jar_fleet_events (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    product_id  UUID NOT NULL REFERENCES products(id),
    event_type  TEXT NOT NULL CHECK (event_type IN ('NEW_PURCHASED','DESTROYED','WASHED')),
    qty         INT NOT NULL CHECK (qty > 0),
    reason_code TEXT CHECK (reason_code IN ('WASH_REJECT','CRACKED','LEAKING','DAMAGED_RETURN','AGE_RETIRED','LOST','OTHER')),
    location    TEXT CHECK (location IN ('PLANT_EMPTY','PLANT_CLEAN','CUSTOMER','VEHICLE')),
    customer_id UUID REFERENCES customers(id),
    trip_id     UUID REFERENCES loading_trips(id),
    supplier_id UUID REFERENCES suppliers(id),
    note        TEXT NOT NULL DEFAULT '',
    created_by  UUID REFERENCES users(id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK ((event_type = 'DESTROYED') = (reason_code IS NOT NULL))
);
CREATE INDEX jar_fleet_events_idx ON jar_fleet_events (product_id, event_type, created_at DESC);
CREATE TRIGGER evt_jar_fleet_events AFTER INSERT OR UPDATE OR DELETE ON jar_fleet_events FOR EACH STATEMENT EXECUTE FUNCTION erp_notify('jars');

INSERT INTO system_settings (key, value, description) VALUES
 ('jars.destroy_warn_pct', '3', 'Alert when containers destroyed in the last 30 days exceed this % of containers filled in that period');

-- ===== migrations/0014_jar_holding_guard.sql =====
-- Safety net (C2): the jars a customer holds can never be negative, whichever module writes jar_ledger
-- (counter receive, trip settlement, write-offs ...). The check is DEFERRED to COMMIT so that the order of rows inside one
-- transaction does not matter, and every (customer, product) pair is serialised with a transaction-level advisory lock so that two
-- concurrent returns cannot both pass. Violation => SQLSTATE 23514 (mapped to HTTP 400 by AppError).
CREATE FUNCTION jar_ledger_guard_holding() RETURNS trigger AS $$
DECLARE held BIGINT;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('jar:' || NEW.customer_id::text || ':' || NEW.product_id::text, 0));
    SELECT COALESCE(SUM(delta), 0) INTO held FROM jar_ledger WHERE customer_id = NEW.customer_id AND product_id = NEW.product_id;
    IF held < 0 THEN
        RAISE EXCEPTION 'customer would hold a negative number of containers (%)', held USING ERRCODE = '23514', CONSTRAINT = 'jar_ledger_holding_non_negative';
    END IF;
    RETURN NULL;
END; $$ LANGUAGE plpgsql;

CREATE CONSTRAINT TRIGGER jar_ledger_holding_non_negative AFTER INSERT ON jar_ledger
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION jar_ledger_guard_holding();

-- ===== migrations/0015_godowns.sql =====
-- Multi-godown inventory. One inventory (stock_balances + stock_ledger) keyed by LOCATION; each godown has its own balances per
-- zone/item/lot and its own FEFO queue. Existing rows belong to the MAIN plant location, so everything written before this
-- migration (and code that does not name a location) keeps working unchanged.
CREATE TABLE locations (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code               TEXT NOT NULL UNIQUE,
    name               TEXT NOT NULL,
    kind               TEXT NOT NULL DEFAULT 'GODOWN' CHECK (kind IN ('PLANT','GODOWN','TRANSIT')),
    address            TEXT NOT NULL DEFAULT '',
    city               TEXT NOT NULL DEFAULT '',
    contact_person     TEXT NOT NULL DEFAULT '',
    phone              TEXT NOT NULL DEFAULT '',
    is_production_site BOOLEAN NOT NULL DEFAULT false,   -- production batches / blow runs / QC happen only at production sites
    is_active          BOOLEAN NOT NULL DEFAULT true,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
INSERT INTO locations (id, code, name, kind, is_production_site) VALUES
 ('00000000-0000-0000-0000-000000000001', 'MAIN',    'Main Plant',          'PLANT',   true),
 ('00000000-0000-0000-0000-000000000002', 'TRANSIT', 'In transit (system)', 'TRANSIT', false);

ALTER TABLE stock_balances ADD COLUMN location_id UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001' REFERENCES locations(id);
ALTER TABLE stock_balances DROP CONSTRAINT stock_balances_item_type_item_id_zone_lot_id_key;
ALTER TABLE stock_balances ADD CONSTRAINT stock_balances_loc_item_uq UNIQUE (location_id, item_type, item_id, zone, lot_id);
CREATE INDEX stock_balances_loc_idx ON stock_balances (location_id, zone, item_type, item_id);
ALTER TABLE stock_ledger ADD COLUMN location_id UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001';
CREATE INDEX stock_ledger_loc_idx ON stock_ledger (location_id, at DESC);

-- Documents remember the godown they act on (default MAIN)
ALTER TABLE grns             ADD COLUMN location_id UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001' REFERENCES locations(id);
ALTER TABLE loading_trips    ADD COLUMN location_id UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001' REFERENCES locations(id); -- source godown
ALTER TABLE dispatch_notes   ADD COLUMN location_id UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001' REFERENCES locations(id);
ALTER TABLE stock_write_offs ADD COLUMN location_id UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001' REFERENCES locations(id);
ALTER TABLE stock_counts     ADD COLUMN location_id UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001' REFERENCES locations(id);
ALTER TABLE supplier_returns ADD COLUMN location_id UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001' REFERENCES locations(id);
ALTER TABLE jar_fleet_events ADD COLUMN location_id UUID REFERENCES locations(id);
ALTER TABLE production_batches ADD COLUMN location_id UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001' REFERENCES locations(id); -- production site
ALTER TABLE blow_molding_runs  ADD COLUMN location_id UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001' REFERENCES locations(id);

-- Users may be limited to some godowns ([] = all godowns)
ALTER TABLE users ADD COLUMN allowed_location_ids JSONB NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(allowed_location_ids) = 'array');

-- Inter-godown transfers: stock leaves the source immediately into the system TRANSIT location, and is booked into the
-- destination only when the receiving godown confirms (with shortage / damage recorded). Nothing ever "disappears".
CREATE SEQUENCE tf_seq;
CREATE TABLE godown_transfers (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tf_no            TEXT NOT NULL UNIQUE,
    from_location_id UUID NOT NULL REFERENCES locations(id),
    to_location_id   UUID NOT NULL REFERENCES locations(id),
    status           TEXT NOT NULL DEFAULT 'IN_TRANSIT' CHECK (status IN ('IN_TRANSIT','RECEIVED','CANCELLED')),
    vehicle_id       UUID REFERENCES vehicles(id),
    vehicle_no       TEXT NOT NULL DEFAULT '',
    driver_name      TEXT NOT NULL DEFAULT '',
    note             TEXT NOT NULL DEFAULT '',
    created_by       UUID REFERENCES users(id),
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    received_by      UUID REFERENCES users(id),
    received_at      TIMESTAMPTZ,
    cancel_reason    TEXT,
    CHECK (from_location_id <> to_location_id)
);
CREATE TABLE godown_transfer_lines (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    transfer_id   UUID NOT NULL REFERENCES godown_transfers(id) ON DELETE CASCADE,
    item_type     TEXT NOT NULL CHECK (item_type IN ('RAW','PRODUCT')),
    item_id       UUID NOT NULL,
    lot_id        UUID NOT NULL,
    zone          TEXT NOT NULL CHECK (zone IN ('RM_STORE','FG_READY','JAR_EMPTY','JAR_CLEAN','BLOW_FLOOR')),  -- never QC_QUARANTINE / SCRAP
    qty_sent      NUMERIC(18,4) NOT NULL CHECK (qty_sent > 0),
    qty_received  NUMERIC(18,4) CHECK (qty_received IS NULL OR qty_received >= 0),
    qty_damaged   NUMERIC(18,4) CHECK (qty_damaged IS NULL OR qty_damaged >= 0),
    note          TEXT NOT NULL DEFAULT ''
);
CREATE INDEX godown_transfers_status_idx ON godown_transfers (status, created_at DESC);

DO $$ DECLARE r RECORD; BEGIN
  FOR r IN SELECT * FROM (VALUES ('locations','master'), ('godown_transfers','stock'), ('godown_transfer_lines','stock')) AS t(tbl, topic) LOOP
    EXECUTE format('CREATE TRIGGER %I AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH STATEMENT EXECUTE FUNCTION erp_notify(%L)', 'evt_'||r.tbl, r.tbl, r.topic);
  END LOOP; END $$;

-- ===== migrations/0020_branding.sql =====
-- Company branding: Neersagar. Only replaces the untouched factory defaults (never overwrites a value an Admin has set).
UPDATE system_settings SET value = '"Neersagar"' WHERE key = 'plant.name' AND value = '"Aqua Pure Plant"';
UPDATE system_settings SET value = '"NSG"'       WHERE key = 'plant.code' AND value = '"PLT1"';
